import React from "react";
import { AppIcon } from "./SVGFiles";

export const UserTopNav: React.FC = () => {
    return (
        <div className="ss-app-config-user-top-nav">
            <a role={"button"} href={process.env.REACT_APP_HELP_URL as string} target="_blank" rel="noreferrer">
                <AppIcon asset="help" height="30" width="30" />
            </a>
        </div>
    );
};
