import React from "react";
import { Col, Form, Input, Row, Spin, Switch } from "antd";
import { AnnouncementConfig } from "../../types";
import { getAnnounements, saveAnnounements } from "../../remote";
import { ConfigHeading } from "../ConfigHeading";
import FileInputUploader from "../FileInputUploader";

export const AppAnnouncement = () => {
  const [formValues, setFormValues] = React.useState<AnnouncementConfig>();
  const [formDisabled, setFormDisabled] = React.useState(false);
  const [form] = Form.useForm<AnnouncementConfig>();

  React.useEffect(() => {
    fetchAnnouncements();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchAnnouncements = async () => {
    const { status, data } = await getAnnounements();
    if (status === 200) {
      setFormValues(data);
      form.setFieldsValue(data);
    }
  };

  const onFinish = async (values: AnnouncementConfig) => {
    setFormDisabled(true);
    if (formValues) {
      const newValues = {
        ...formValues,
        ...values,
      };
      await saveAnnounements(formValues.Id, newValues).catch(() => setFormDisabled(false));
      setFormValues(newValues);
    }
    setFormDisabled(false);
  };

  if (!formValues) {
    return null;
  }

  return (
    <Spin
      spinning={formValues === undefined || formDisabled}
      tip={formDisabled ? "Saving configuration" : "Loading My Pay configuration"}>
      <Form
        name="ss-links"
        onFinish={onFinish}
        initialValues={formValues}
        autoComplete={"off"}
        layout="vertical"
        form={form}
        disabled={formDisabled}>
        <ConfigHeading title="Announcements Config" />
        <div className="ss-app-config-box shadow ss-app-config-dashboard">
          <Form.Item name={["Id"]} noStyle>
            <Input type="hidden" />
          </Form.Item>
          <Form.Item name={["MobileAppLinks", "AppleAppStore"]} noStyle>
            <Input type="hidden" />
          </Form.Item>
          <Form.Item name={["MobileAppLinks", "GooglePlayStore"]} noStyle>
            <Input type="hidden" />
          </Form.Item>
          <Row gutter={20}>
            <Col xs={24}>
              <Form.Item name={["MobileAppLinks", "Read"]} label="Show App Links" valuePropName="checked">
                <Switch />
              </Form.Item>
            </Col>
            {/* <Col xs={24} sm={12} md={8}>
                            <Form.Item name={["MobileAppLinks", "AppleAppStore"]} label="Apple App Store">
                                <Input />
                            </Form.Item>
                        </Col>
                        <Col xs={24} sm={12} md={8}>
                            <Form.Item name={["MobileAppLinks", "GooglePlayStore"]} label="Google Play Store">
                                <Input />
                            </Form.Item>
                        </Col> */}
          </Row>
          {/* <hr /> */}
          {/* <Form.List name={["Announcements"]}>
                        {(fields, { add, remove }) => {
                            return (
                                <div className="ss-app-config-form-list">
                                    <h3>
                                        <span>Announcements</span>
                                    </h3>
                                    {fields.map(({ name }, _Indx) => {
                                        return (
                                            <div className="ss-app-config-form-item">
                                                <Form.Item name={[name, "Read"]} noStyle>
                                                    <Input type="hidden" />
                                                </Form.Item>
                                                <Form.Item name={[name, "Id"]} noStyle>
                                                    <Input type="hidden" />
                                                </Form.Item>
                                                <Form.Item name={[name, "Banner"]} label="Announcement Banner image">
                                                    <FileInputUploader />
                                                </Form.Item>
                                                <Form.Item
                                                    name={[name, "Title"]}
                                                    rules={[{ required: true, message: "Please input the Title." }]}
                                                    label="Announcement Title">
                                                    <Input />
                                                </Form.Item>
                                                <Form.Item
                                                    name={[name, "Message"]}
                                                    rules={[{ required: true, message: "Please input the Message." }]}
                                                    label="Announcement Message">
                                                    <Input.TextArea rows={4} />
                                                </Form.Item>
                                                <Form.Item name={[name, "FooterNote"]} label="Announcement Footer Note">
                                                    <Input.TextArea rows={2} />
                                                </Form.Item>
                                                <h4>
                                                    <span>Image links</span>
                                                </h4>
                                                <ImageLinks name={name} />
                                            </div>
                                        );
                                    })}
                                </div>
                            );
                        }}
                    </Form.List> */}
        </div>
      </Form>
    </Spin>
  );
};

interface Props {
  name: number;
}

export const ImageLinks: React.FC<Props> = ({ name }) => {
  return (
    <Form.List name={[name, "ImageLinks"]}>
      {(fields, { add, remove }) => {
        return (
          <Row gutter={20}>
            {fields.map(({ name }, _Indx) => {
              return (
                <Col md={12}>
                  <Row gutter={20}>
                    <Col flex={"none"}>
                      <Form.Item name={[name, "Image"]} label="Image">
                        <FileInputUploader />
                      </Form.Item>
                    </Col>
                    <Col flex={"auto"}>
                      <Form.Item
                        name={[name, "Label"]}
                        rules={[{ required: true, message: "Please input the Label." }]}
                        label="Image Label">
                        <Input />
                      </Form.Item>
                      <Form.Item
                        name={[name, "Url"]}
                        rules={[{ required: true, message: "Please input the Link." }]}
                        label="Link">
                        <Input />
                      </Form.Item>
                      <Form.Item name={[name, "AltText"]} label="Alternative Text">
                        <Input />
                      </Form.Item>
                    </Col>
                  </Row>
                </Col>
              );
            })}
          </Row>
        );
      }}
    </Form.List>
  );
};
