import React from "react";
import { NavigationRoute } from "../types";

import { AppIcon } from "./SVGFiles";
import { Button } from "antd";
import { AppContext, setActivePage } from "../context";
import PerfectScrollbar from "react-perfect-scrollbar";
import { Link } from "react-router-dom";

interface Props {
    showFullMenu: boolean;
    onCollapseBtnClick: () => void;
}

export const AppNavigator: React.FC<Props> = ({ showFullMenu, onCollapseBtnClick }) => {
    const { state, dispatch } = React.useContext(AppContext);

    React.useEffect(() => {
        if (showFullMenu) {
            document.body.classList.add("menu-show-full");
        } else {
            document.body.classList.remove("menu-show-full");
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [showFullMenu]);

    return (
        <div className="ss-app-config-navigator">
            <div className="ss-app-config-navigator-wrapper">
                <PerfectScrollbar options={{ suppressScrollX: true }}>
                    <AppNavLink
                        label="Dashboard"
                        icon="dashboard"
                        id="Dashboard"
                        isActive={state.activePage === "Dashboard"}
                        onClick={() => dispatch(setActivePage("Dashboard" === state.activePage ? "" : "Dashboard"))}
                    />
                    {state.navLinks.length
                        ? state.dashboardLinks
                              .filter((nav) => nav.Link.Enabled)
                              .map((navProps, i) => {
                                  const isActive = navProps.Name === state.activePage;
                                  return (
                                      <AppNavLink
                                          label={navProps.Link.Text}
                                          icon={navProps.Link.Icon}
                                          id={navProps.Name}
                                          isActive={isActive}
                                          onClick={() =>
                                              dispatch(
                                                  setActivePage(navProps.Name === state.activePage ? "" : navProps.Name)
                                              )
                                          }
                                          key={i}
                                      />
                                  );
                              })
                        : null}

                    <AppNavLink
                        label="Document Signature"
                        icon="doc-check"
                        id="DocumentSignatures"
                        isActive={state.activePage === "DocumentSignatures"}
                        onClick={() =>
                            dispatch(
                                setActivePage("DocumentSignatures" === state.activePage ? "" : "DocumentSignatures")
                            )
                        }
                    />

                    <AppNavLink
                        label="Announcements"
                        icon="announcement"
                        id="Announcements"
                        isActive={state.activePage === "Announcements"}
                        onClick={() =>
                            dispatch(setActivePage("Announcements" === state.activePage ? "" : "Announcements"))
                        }
                    />

                    <AppNavLink
                        link={process.env.REACT_APP_LOGOUT_URL as string}
                        label="Logout"
                        icon="logout"
                        id="logout"
                        isAnchor={true}
                    />
                </PerfectScrollbar>
            </div>
            <Button
                onClick={() => onCollapseBtnClick()}
                type="link"
                className="ss-app-config-navigator-close"
                icon={<AppIcon height="36" width="36" asset="close" stroke="#344356" />}
            />
        </div>
    );
};

interface NavLink extends NavigationRoute {
    className?: string;
    isActive?: boolean;
    isGrid?: boolean;
    isAnchor?: boolean;
    onClick?: (id: string) => void;
}

export const AppNavLink: React.FC<NavLink> = ({
    label,
    icon,
    id = "",
    className,
    isActive = false,
    isGrid = false,
    isAnchor = false,
    link = "",
    onClick,
}) => {
    let linkAttr: any = {
        role: "button",
        onClick: () => onClick && onClick(id),
        className: `ss-app-config-nav-item${isActive !== undefined ? (isActive ? " active" : "") : ""}`,
        to: id !== "collapse" && !isAnchor ? `/${id}` : undefined,
        href: isAnchor ? link : undefined,
    };

    const linkContent = (
        <>
            <AppIcon className="link-icon" asset={icon} />
            <span className="ss-app-config-nav-item-label">{label}</span>
            {!isGrid && (
                <>
                    <span className="ss-app-config-nav-item-edge ss-app-config-nav-item-top-edge">
                        <AppIcon asset={"menu-edge-top"} />
                    </span>
                    <span className="ss-app-config-nav-item-edge ss-app-config-nav-item-bottom-edge">
                        <AppIcon asset={"menu-edge-bottom"} />
                    </span>
                </>
            )}
        </>
    );

    return (
        <div className={`link-item-wrapper ${className || ""}`}>
            {isAnchor ? (
                <a {...linkAttr}>{linkContent}</a>
            ) : (
                <Link replace={true} {...linkAttr}>
                    {linkContent}
                </Link>
            )}
        </div>
    );
};
